<script lang="ts">
 import {onMount} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {listen} from '@tauri-apps/api/event';
 import {Mic, AudioLines, Clock3, NotebookPen, Settings2, Search, Plus, ArrowUpRight, ArrowDownToLine, Check, X, Square, Copy, Trash2, ChevronRight, ChevronLeft, FileAudio, LoaderCircle, Sparkles, Download, RotateCcw, ArrowUp, Command, ShieldCheck, Circle, MoreHorizontal, SlidersHorizontal, Globe2, Keyboard, BookOpen, Sun, Moon} from 'lucide-svelte';
 type Entry={id:string;kind:string;title:string;text:string;notes:string;summary:string;created:string;duration:number;status:string;segments:string};
 type Config={model:string;stt_mode:string;stt_url:string;stt_model:string;speaker_python:string;language:string;microphone:string;shortcut:string;hold_to_talk:boolean;theme:string;retain_audio:boolean;system_audio:boolean;history_days:number;ai_url:string;ai_model:string;ai_kind:string;google_client_id:string;microsoft_client_id:string;vocabulary:string[];snippets:{trigger:string;text:string}[]};
 type InstalledModel={id:string;installed:boolean;custom?:boolean;name?:string;repo?:string;filename?:string;size?:number;revision?:string};
 type HubFile={name:string;size:number;compatible:boolean;reason:string};
 type HubRepository={repo:string;revision:string;license:string;files:HubFile[]};
 let showHub=$state(false), hubRepo=$state(''), hubRevision=$state('main'), hubToken=$state(''), hubInfo=$state<HubRepository|null>(null), hubFile=$state('');
 const hubSelection=$derived(hubInfo?.files.find(f=>f.name===hubFile));
 const bytes=(n:number)=>n>=1024**3?`${(n/1024**3).toFixed(2)} GB`:`${(n/1024**2).toFixed(1)} MB`;
 async function inspectHub(){hubInfo=null;hubFile='';await action(async()=>{hubInfo=await call<HubRepository>('inspect_hf_model',{repo:hubRepo,revision:hubRevision,token:hubToken});hubFile=hubInfo.files.find(f=>f.compatible)?.name||'';},'hf-search');}
 async function importHub(){if(!hubInfo||!hubSelection?.compatible)return;const info=hubInfo;const filename=hubFile;downloading='huggingface';downloadPercent=0;await action(async()=>{const model=await call<InstalledModel>('import_hf_model',{repo:info.repo,revision:info.revision,filename,token:hubToken});hubToken='';config.model=model.id;config.stt_mode='local';await call('save_settings',{settings:config});await refresh();toast('Model installed and selected');});downloading='';}
 let speakerKey=$state(''), showSegments=$state(false);
 let speechKey=$state(''), undoText=$state(''), cleanupStyle=$state('Natural');
 let calendarProvider=$state('google'), calendarSecret=$state(''), events=$state<any[]>([]);
 let page=$state('history'), settingsTab=$state('general'), query=$state(''), entries=$state<Entry[]>([]), selected=$state<Entry|null>(null), detailTab=$state('transcript');
 let config=$state<Config>({model:'base',stt_mode:'local',stt_url:'',stt_model:'',speaker_python:'',language:'auto',microphone:'',shortcut:'CommandOrControl+Shift+Space',hold_to_talk:false,theme:'system',retain_audio:false,system_audio:false,history_days:30,ai_url:'http://localhost:11434',ai_model:'qwen3:4b',ai_kind:'ollama',google_client_id:'',microsoft_client_id:'',vocabulary:[],snippets:[]});
 let models=$state<InstalledModel[]>([]), devices=$state<string[]>([]), phase=$state('idle'), level=$state(0), elapsed=$state(0), error=$state(''), notice=$state(''), busy=$state(''), downloading=$state(''), downloadPercent=$state(0), progress=$state(0), key=$state(''), question=$state(''), answer=$state(''), vocabulary=$state(''), trigger=$state(''), expansion=$state(''), engine=$state(false), platform=$state('macos'), deleteId=$state('');
 const overlay=new URLSearchParams(window.location.search).has('overlay');
 const native=typeof window!=='undefined'&&'__TAURI_INTERNALS__' in window;
 const descriptions:Record<string,{name:string;size:string;desc:string}>={tiny:{name:'Light',size:'~31 MB download',desc:'Smallest footprint. Best for clear, simple speech.'},base:{name:'Everyday',size:'~60 MB download',desc:'A balanced starting point for multilingual dictation.'},small:{name:'Precise',size:'~190 MB download',desc:'Better recognition, with more memory while processing.'},turbo:{name:'Studio',size:'~570 MB download',desc:'Highest accuracy option. Requires substantially more RAM.'}};
 const languages=[['auto','Detect automatically'],['en','English'],['nl','Dutch'],['de','German'],['fr','French'],['es','Spanish'],['it','Italian'],['pt','Portuguese'],['ar','Arabic'],['hi','Hindi'],['ja','Japanese'],['zh','Chinese'],['ko','Korean'],['ru','Russian'],['uk','Ukrainian'],['tr','Turkish'],['pl','Polish'],['sv','Swedish'],['id','Indonesian']];
 const filtered=$derived(entries.filter(e=>e.kind===(page==='meetings'?'meeting':'dictation')&&`${e.title} ${e.text} ${e.notes}`.toLowerCase().includes(query.toLowerCase())));
 const modelReady=$derived((config.stt_mode==='cloud'||models.some(m=>m.id===config.model&&m.installed)));
 const words=$derived(entries.filter(e=>e.kind==='dictation').reduce((n,e)=>n+e.text.split(/\s+/).filter(Boolean).length,0));
 const clock=(s:number)=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
 const date=(s:string)=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});
 async function call<T=unknown>(cmd:string,args:Record<string,unknown>={}):Promise<T>{if(!native)throw new Error('Open the QuickTalk desktop app to use this feature.');return invoke<T>(cmd,args);}
 async function refresh(){if(!native)return;const data=await call<any>('bootstrap');config=data.settings;entries=data.entries;models=data.models;devices=data.devices;engine=data.engine;platform=data.platform;phase=data.phase;if(selected){selected=entries.find(e=>e.id===selected?.id)||null;}}
 async function action(fn:()=>Promise<unknown>,label=''){error='';busy=label;try{await fn();}catch(e){error=String(e);}finally{busy='';}}
 function toast(s:string){notice=s;setTimeout(()=>notice='',3000);}
 async function save(){await action(async()=>{await call('save_settings',{settings:config});toast('Settings saved');});}
 async function record(){await action(async()=>{if(phase==='recording'){await call('stop_recording');}else{elapsed=0;await call('start_recording',{kind:page==='meetings'?'meeting':'dictation'});}await refresh();});}
 async function getModel(id:string){downloading=id;downloadPercent=0;await action(async()=>{await call('download_model',{id});config.model=id;await call('save_settings',{settings:config});await refresh();toast('Model ready. You can start talking.');});downloading='';}
 async function openEntry(e:Entry){undoText='';answer='';selected={...e};detailTab=e.kind==='meeting'?'notes':'transcript';}
 async function saveEntry(){if(!selected)return;await action(async()=>{await call('update_entry',{id:selected!.id,title:selected!.title,notes:selected!.notes,text:selected!.text});await refresh();toast('Changes saved');});}
 async function summarize(){if(!selected)return;await action(async()=>{await saveEntry();selected!.summary=await call<string>('summarize',{id:selected!.id});detailTab='summary';await refresh();},'summary');}
 async function ask(){if(!question.trim())return;await action(async()=>{answer=await call<string>('ask_meetings',{question,ids:selected?[selected.id]:[]});},'ask');}
 async function remove(){await action(async()=>{await call('delete_entry',{id:deleteId});deleteId='';selected=null;await refresh();toast('Recording deleted');});}
 onMount(()=>{if(overlay)phase='recording';let unsubs:(()=>void)[]=[];let disposed=false;if(!overlay)action(refresh);if(native){Promise.all([listen<string>('phase',e=>{phase=e.payload;if(phase==='recording')elapsed=0;}),listen<number>('level',e=>level=e.payload),listen('changed',()=>{if(!overlay)action(refresh);}),listen<string>('error',e=>error=e.payload),listen<any>('progress',e=>progress=e.payload.fraction),listen<any>('download',e=>downloadPercent=e.payload.total?e.payload.received/e.payload.total*100:0)]).then(xs=>{if(disposed)xs.forEach(x=>x());else unsubs=xs;});}const timer=setInterval(()=>{if(phase==='recording')elapsed+=1;},1000);return()=>{disposed=true;clearInterval(timer);unsubs.forEach(f=>f());};});
 $effect(()=>{document.documentElement.dataset.theme=config.theme;});
</script>
<svelte:head><title>QuickTalk · A little less typing.</title></svelte:head>
{#if overlay}<div class="overlay-pill"><span class="record-dot"></span><AudioLines size={20}/><span>{phase==='processing'?'Transcribing…':'Listening…'}</span><small>{clock(elapsed)}</small></div>{:else}
<div class="app-shell">
 <aside class="sidebar">
  <div class="drag-region" data-tauri-drag-region></div>
  <button class="brand" onclick={()=>{page='history';selected=null;}}><span class="brand-mark"><AudioLines size={20} strokeWidth={2.2}/></span>QuickTalk<span class="beta">BETA</span></button>
  <nav aria-label="Main navigation">
   <button class:active={page==='history'} onclick={()=>{page='history';selected=null;query='';}}><Clock3 size={18}/>History</button>
   <button class:active={page==='meetings'} onclick={()=>{page='meetings';selected=null;query='';}}><NotebookPen size={18}/>Meetings</button>
  </nav>
  <div class="sidebar-bottom">
   <div class="local-note"><span class="small-dot"></span><span>On your device.<br/><strong>Under your control.</strong></span></div>
   <button class:active={page==='settings'} onclick={()=>{page='settings';selected=null;}}><Settings2 size={18}/>Settings</button>
   <div class="sidebar-footer"><span>QuickTalk 0.1</span><span class="key-hint">⌘</span></div>
  </div>
 </aside>
 <main>
  <div class="topbar" data-tauri-drag-region><span>{page==='settings'?'Your preferences':page==='meetings'?'A clearer record of the conversation':'A little less typing.'}</span><div class="privacy-badge"><ShieldCheck size={13}/>{config.stt_mode==='cloud'?'Cloud transcription':'Local transcription'}</div></div>
  {#if !native}<div class="preview-note">Design preview · recording and storage are available in the desktop app.</div>{/if}
  {#if error}<div class="message error" role="alert"><span>{error}</span><button class="icon-button" aria-label="Dismiss error" onclick={()=>error=''}><X size={16}/></button></div>{/if}
  {#if page==='settings'}
   <header class="page-header"><div><p class="eyebrow">MAKE IT YOURS</p><h1>Settings</h1><p>Just the essentials. Everything else stays out of your way.</p></div></header>
   <div class="tabs settings-tabs">{#each [['general','General'],['models','Speech models'],['words','Words & snippets'],['ai','AI & privacy'],['calendar','Calendars']] as [id,label]}<button class:chosen={settingsTab===id} onclick={()=>settingsTab=id}>{label}</button>{/each}</div>
   <div class="settings-content">
   {#if settingsTab==='general'}
    <section class="setting-group"><h2>Recording</h2><label class="setting-row"><span><strong>Microphone</strong><small>Your voice starts here.</small></span><select bind:value={config.microphone} onchange={save}><option value="">System default</option>{#each devices as d}<option value={d}>{d}</option>{/each}</select></label>
    <label class="setting-row"><span><strong>Language</strong><small>Keep the original language of your speech.</small></span><select bind:value={config.language} onchange={save}>{#each languages as [id,label]}<option value={id}>{label}</option>{/each}</select></label>
    <label class="setting-row"><span><strong>Recording shortcut</strong><small>Works while QuickTalk is in the background.</small></span><input class="shortcut-input" bind:value={config.shortcut} onblur={save}/></label>
    <label class="setting-row"><span><strong>Hold to talk</strong><small>Release the shortcut to finish.</small></span><input class="switch" type="checkbox" bind:checked={config.hold_to_talk} onchange={save}/></label></section>
    <section class="setting-group"><h2>Meetings</h2><label class="setting-row"><span><strong>Include computer audio</strong><small>Capture remote participants on a separate track. Headphones recommended.</small></span><input class="switch" type="checkbox" bind:checked={config.system_audio} onchange={save}/></label></section>
    <section class="setting-group"><h2>Appearance</h2><label class="setting-row"><span><strong>Color theme</strong><small>A comfortable space, day or night.</small></span><select bind:value={config.theme} onchange={save}><option value="system">Follow system</option><option value="light">Light</option><option value="dark">Dark</option></select></label></section>
    <div class="quiet-card"><Keyboard size={18}/><p>On macOS, allow QuickTalk in <strong>Privacy & Security → Microphone</strong> and <strong>Accessibility</strong> to dictate into other apps. Start from the shortcut to keep your cursor in place.</p></div>
   {:else if settingsTab==='models'}
    <label class="setting-row"><span><strong>Transcription</strong><small>Cloud mode sends recorded audio to your chosen provider.</small></span><select bind:value={config.stt_mode} onchange={save}><option value="local">On this device</option><option value="cloud">Cloud · my API key</option></select></label>
    {#if config.stt_mode==='cloud'}<section class="setting-group"><label class="stacked-label">Transcription endpoint<input bind:value={config.stt_url} onblur={save} placeholder="https://your-provider.example/v1/audio/transcriptions"/></label><label class="stacked-label">Model<input bind:value={config.stt_model} onblur={save}/></label><label class="stacked-label">Speech API key<input type="password" bind:value={speechKey}/></label><button class="secondary" onclick={()=>action(async()=>{await call('save_speech_key',{key:speechKey});speechKey='';toast('Speech API key saved securely');})}>Save speech API key</button></section>{/if}
    <div class="section-intro"><h2>Good words. Small footprint.</h2><p>Models download once and work offline. Memory is released after every transcription.</p></div>
    {#if native&&!engine}<div class="message error">Speech engine is missing from this build. Run the engine setup script before packaging.</div>{/if}
    {#each ['tiny','base','small','turbo'] as id}<div class="model-card" class:selected-model={config.model===id}><div class="model-symbol"><AudioLines size={22}/></div><div class="model-copy"><div class="model-heading"><h3>{descriptions[id].name}</h3>{#if id==='base'}<span class="tag">RECOMMENDED</span>{/if}</div><p>{descriptions[id].desc}</p><small>{descriptions[id].size} · Multilingual</small></div><div class="model-actions">{#if downloading===id}<span class="download-label"><LoaderCircle size={15} class="spin"/>{downloadPercent?`${Math.round(downloadPercent)}%`:'Downloading'}</span><button class="text-button" onclick={()=>call('cancel_model_download')}>Cancel</button>{:else if models.some(m=>m.id===id&&m.installed)}<button class="secondary small" onclick={()=>{config.model=id;save();}}>{#if config.model===id}<Check size={14}/>Selected{:else}Use model{/if}</button><button class="icon-button" aria-label={`Remove ${id} model`} onclick={()=>action(async()=>{await call('delete_model',{id});await refresh();})}><Trash2 size={14}/></button>{:else}<button class="secondary small" disabled={!!downloading} onclick={()=>getModel(id)}><Download size={14}/>Download</button>{/if}</div></div>{/each}
    {#each models.filter(m=>m.custom) as model (model.id)}
     <div class="model-card" class:selected-model={config.model===model.id}>
      <div class="model-symbol"><AudioLines size={22}/></div>
      <div class="model-copy"><div class="model-heading"><h3>{model.name}</h3><span class="tag">HUGGING FACE</span></div><p>{model.repo}</p><small>{bytes(model.size||0)} on disk · Revision {model.revision?.slice(0,8)}</small></div>
      <div class="model-actions"><button class="secondary small" onclick={()=>{config.model=model.id;config.stt_mode='local';save();}}>{#if config.model===model.id}<Check size={14}/>Selected{:else}Use model{/if}</button><button class="icon-button" disabled={config.model===model.id||!!downloading||phase!=='idle'} title={config.model===model.id?'Select another model to remove this one':'Remove model'} aria-label={`Remove ${model.name} model`} onclick={()=>action(async()=>{await call('delete_model',{id:model.id});await refresh();toast('Model removed');})}><Trash2 size={14}/></button></div>
     </div>
    {/each}
    <section class="hub-section">
     <button class="hub-toggle" aria-expanded={showHub} disabled={downloading==='huggingface'} onclick={()=>showHub=!showHub}><span><Globe2 size={17}/><strong>From Hugging Face</strong></span>{#if showHub}<X size={15}/>{:else}<Plus size={17}/>{/if}</button>
     <p class="muted">Bring your own speech model. Download once, use offline.</p>
     {#if showHub}
      <form onsubmit={e=>{e.preventDefault();inspectHub();}}>
       <label class="stacked-label">Model repository<input bind:value={hubRepo} oninput={()=>{hubInfo=null;hubFile='';}} placeholder="owner/model or https://huggingface.co/owner/model" required disabled={!!downloading}/></label>
       <details class="hub-options"><summary>Revision & private models</summary><label class="stacked-label">Branch, tag or commit<input bind:value={hubRevision} oninput={()=>{hubInfo=null;hubFile='';}} placeholder="main" disabled={!!downloading}/></label><label class="stacked-label">Read token · optional<input type="password" bind:value={hubToken} autocomplete="off" placeholder="hf_…" disabled={!!downloading}/></label><p class="fine-print">The token stays in memory for this import. For gated models, accept access terms on Hugging Face first.</p></details>
       <button type="submit" class="secondary" disabled={!hubRepo.trim()||!!downloading||busy==='hf-search'}>{#if busy==='hf-search'}<LoaderCircle size={14} class="spin"/>Finding files…{:else}<Search size={14}/>Find model files{/if}</button>
      </form>
      {#if hubInfo}
       <div class="hub-results">
        <p class="fine-print">{hubInfo.repo} · License: {hubInfo.license} · Revision {hubInfo.revision.slice(0,8)}</p>
        {#if hubInfo.files.some(f=>f.compatible)}
         <label class="stacked-label">Model file<select class="hub-file-select" bind:value={hubFile} disabled={!!downloading}>{#each hubInfo.files as file}<option value={file.name} disabled={!file.compatible}>{file.name} · {bytes(file.size)}{file.compatible?'':' · Unsupported format'}</option>{/each}</select></label>
         <p class="fine-print">{hubSelection?.reason}. Download size: {bytes(hubSelection?.size||0)}. Larger models use more memory during transcription.</p>
         {#if downloading==='huggingface'}
          <div class="hub-progress" role="status"><span><LoaderCircle size={14} class="spin"/>{downloadPercent?`Downloading · ${Math.round(downloadPercent)}%`:'Connecting to Hugging Face…'}</span><button class="text-button" onclick={()=>call('cancel_model_download')}>Cancel download</button></div><progress aria-label="Model download" value={downloadPercent} max="100"></progress>
         {:else}<button class="primary" disabled={!!downloading||!hubSelection?.compatible} onclick={importHub}><Download size={14}/>Download & use</button>{/if}
        {:else}<div class="quiet-card"><p>No compatible files found. This build runs <strong>Whisper GGML .bin</strong> models made for whisper.cpp. Safetensors, PyTorch, GGUF and other architectures need a different runtime.</p></div>{/if}
       </div>
      {/if}
      <p class="fine-print">Works with Whisper GGML conversions from any repository. Model code is never executed. Try <button class="text-button" disabled={!!downloading} onclick={()=>{hubRepo='ggerganov/whisper.cpp';hubRevision='main';inspectHub();}}>ggerganov/whisper.cpp</button>.</p>
     {/if}
    </section>
   {:else if settingsTab==='words'}
    <section class="setting-group"><h2>Your vocabulary</h2><p class="muted">Names, places, and words you use often. Saved locally.</p><div class="inline-form"><input aria-label="New vocabulary word" bind:value={vocabulary} placeholder="e.g. QuickTalk, Kubernetes, José"/><button class="secondary" onclick={()=>{if(vocabulary.trim()){config.vocabulary=[...config.vocabulary,vocabulary.trim()];vocabulary='';save();}}}><Plus size={15}/>Add word</button></div><div class="chips">{#each config.vocabulary as word}<button onclick={()=>{config.vocabulary=config.vocabulary.filter(w=>w!==word);save();}}>{word}<X size={12}/></button>{/each}</div></section>
    <section class="setting-group"><h2>Say a little. Write a lot.</h2><p class="muted">Say a trigger on its own to insert your saved text.</p><input aria-label="Snippet trigger" bind:value={trigger} placeholder="Spoken trigger, e.g. my signature"/><textarea aria-label="Snippet text" bind:value={expansion} placeholder="The text to insert…" rows="3"></textarea><button class="secondary" onclick={()=>{if(trigger.trim()&&expansion){config.snippets=[...config.snippets,{trigger:trigger.trim(),text:expansion}];trigger='';expansion='';save();}}}><Plus size={15}/>Add snippet</button>{#each config.snippets as s,i}<div class="snippet"><div><strong>{s.trigger}</strong><p>{s.text}</p></div><button class="icon-button" aria-label="Remove snippet" onclick={()=>{config.snippets=config.snippets.filter((_,n)=>n!==i);save();}}><Trash2 size={14}/></button></div>{/each}</section>
   {:else if settingsTab==='ai'}
    <section class="setting-group"><h2>Optional intelligence</h2><p class="muted">Summaries and meeting questions use the provider you choose. Remote providers receive the text you ask them to process.</p><label class="setting-row"><span><strong>Provider</strong></span><select bind:value={config.ai_kind} onchange={save}><option value="ollama">Local · Ollama</option><option value="compatible">Cloud · Compatible API</option></select></label><label class="stacked-label">Service URL<input bind:value={config.ai_url} onblur={save} placeholder="http://localhost:11434"/></label><label class="stacked-label">Model<input bind:value={config.ai_model} onblur={save} placeholder="qwen3:4b"/></label>{#if config.ai_kind!=='ollama'}<label class="stacked-label">API key<input type="password" bind:value={key} placeholder="Stored in your operating system’s credential store"/></label><button class="secondary" onclick={()=>action(async()=>{await call('save_api_key',{key});key='';toast('API key saved securely');})}>Save API key</button>{:else}<div class="quiet-card"><ShieldCheck size={18}/><p>Run Ollama locally and download the model you choose. QuickTalk requests that the model unload after each response.</p></div>{/if}</section>
    <section class="setting-group"><h2>Optional speaker analysis</h2><p class="muted">Run the optional setup script, accept the model’s access terms, and enter the environment’s Python path. This downloads a separate model and can use several GB of memory. Keep original audio enabled for meetings you want to analyze.</p><label class="stacked-label">Speaker environment Python<input bind:value={config.speaker_python} onblur={save}/></label><label class="stacked-label">Hugging Face read token<input type="password" bind:value={speakerKey}/></label><button class="secondary" onclick={()=>action(async()=>{await call('save_speaker_key',{key:speakerKey});speakerKey='';toast('Token stored securely');})}>Save model token</button></section>
    <section class="setting-group"><h2>Your data</h2><label class="setting-row"><span><strong>Keep original audio</strong><small>Allows retranscription. Uses additional disk space.</small></span><input class="switch" type="checkbox" bind:checked={config.retain_audio} onchange={save}/></label><label class="setting-row"><span><strong>Dictation history</strong><small>Meeting notes stay until you delete them.</small></span><select bind:value={config.history_days} onchange={save}><option value={7}>7 days</option><option value={30}>30 days</option><option value={90}>90 days</option><option value={0}>Until I delete it</option></select></label></section>
   {:else}
    <section class="setting-group"><h2>Your next conversation</h2><p class="muted">Connect a calendar with read-only access. No meeting starts recording automatically.</p><label class="setting-row"><span><strong>Calendar service</strong></span><select bind:value={calendarProvider}><option value="google">Google Calendar</option><option value="microsoft">Outlook / Microsoft 365</option></select></label><label class="stacked-label">Desktop OAuth client ID{#if calendarProvider==='google'}<input bind:value={config.google_client_id} onblur={save}/>{:else}<input bind:value={config.microsoft_client_id} onblur={save}/>{/if}</label>{#if calendarProvider==='google'}<label class="stacked-label">Desktop client secret<input type="password" bind:value={calendarSecret}/></label>{/if}<div class="inline-form"><button class="primary" disabled={!!busy} onclick={()=>action(async()=>{await call('save_settings',{settings:config});await call('connect_calendar',{provider:calendarProvider,secret:calendarSecret});calendarSecret='';toast('Calendar connected');},'calendar')}>{busy==='calendar'?'Waiting for sign-in…':'Connect calendar'}</button><button class="secondary" onclick={()=>action(async()=>{await call('disconnect_calendar',{provider:calendarProvider});events=[];toast('Calendar disconnected');})}>Disconnect</button></div><div class="quiet-card"><ShieldCheck size={18}/><p>This open-source build uses your own registered desktop OAuth application. The setup guide explains the client ID and loopback redirect settings. Credentials are kept in your system keychain.</p></div></section>
   {/if}</div>
  {:else if selected}
   <div class="detail-head"><button class="text-button" onclick={()=>selected=null}><ChevronLeft size={15}/>Back to {page}</button><div class="detail-actions"><button class="icon-button" aria-label="Copy transcript" onclick={()=>action(async()=>{await call('copy_text',{text:selected!.text});toast('Copied');})}><Copy size={16}/></button><select class="export-select" aria-label="Export format" onchange={(e)=>{if(e.currentTarget.value)action(()=>call('export_entry',{id:selected!.id,format:e.currentTarget.value}));e.currentTarget.value='';}}><option value="">Export…</option><option value="md">Markdown / Obsidian</option><option value="txt">Plain text</option><option value="srt">Subtitles</option><option value="json">JSON</option></select><button class="icon-button" aria-label="Delete recording" onclick={()=>deleteId=selected!.id}><Trash2 size={16}/></button></div></div>
   <header class="entry-header"><input class="title-input" aria-label="Recording title" bind:value={selected.title}/><div class="entry-meta"><span>{date(selected.created)}</span><span>·</span><span>{clock(selected.duration)}</span><span>·</span><span class="status-chip">{selected.status}</span></div></header>
   <div class="tabs">{#each (selected.kind==='meeting'?['notes','transcript','summary','ask']:['transcript']) as tab}<button class:chosen={detailTab===tab} onclick={()=>detailTab=tab}>{tab==='ask'?'Ask this meeting':tab[0].toUpperCase()+tab.slice(1)}</button>{/each}</div>
   <div class="detail-body">
   {#if detailTab==='notes'}<textarea class="document-editor" bind:value={selected.notes} placeholder="Leave yourself a few notes. A thought, a decision, something to follow up on…" aria-label="Meeting notes"></textarea><button class="secondary" onclick={saveEntry}><Check size={15}/>Save notes</button>
   {:else if detailTab==='transcript'}{#if selected.kind==='meeting'&&selected.text}<div class="inline-form"><button class="text-button" onclick={()=>showSegments=!showSegments}>{showSegments?'Hide timestamps':'Show timestamps & speakers'}</button><button class="text-button" disabled={!!busy} onclick={()=>action(async()=>{await call('analyze_speakers',{id:selected!.id});await refresh();showSegments=true;},'speakers')}>{busy==='speakers'?'Analyzing speakers…':'Analyze speakers'}</button></div>{#if showSegments}<div class="segments">{#each JSON.parse(selected.segments) as seg}<div><span>{clock(seg.start)} · {seg.speaker}</span><p>{seg.text}</p></div>{/each}</div>{/if}{/if}{#if selected.text}<textarea class="document-editor" bind:value={selected.text} aria-label="Transcript"></textarea><div class="inline-form"><button class="secondary" onclick={saveEntry}><Check size={15}/>Save edits</button><select aria-label="Cleanup style" bind:value={cleanupStyle}><option>Natural</option><option>Formal</option><option>Casual</option></select><button class="secondary" disabled={!!busy} onclick={()=>action(async()=>{const original=selected!.text;const cleaned=await call<string>('clean_text',{text:original,style:cleanupStyle});undoText=original;selected!.text=cleaned;},'cleanup')}><Sparkles size={14}/>{busy==='cleanup'?'Cleaning…':'Clean up'}</button>{#if undoText}<button class="text-button" onclick={()=>{selected!.text=undoText;undoText='';}}>Undo</button>{/if}</div>{:else}<div class="empty-detail"><AudioLines size={28}/><h3>{selected.status==='processing'?'Finding your words…':'Your transcript will appear here'}</h3><p>{selected.status==='failed'||selected.status==='interrupted'?'Your recording is saved. Check your model and try again.':'Finish recording to transcribe the audio locally.'}</p></div>{/if}{#if selected.status!=='recording'&&selected.status!=='processing'}<button class="text-button retry" onclick={()=>action(()=>call('retry',{id:selected!.id}))}><RotateCcw size={14}/>Transcribe again</button>{/if}
   {:else if detailTab==='summary'}{#if selected.summary}<div class="generated-text">{selected.summary}</div>{:else}<div class="empty-detail"><Sparkles size={28}/><h3>The important parts, together.</h3><p>Turn your transcript and notes into a useful summary<br/>with decisions and next steps.</p></div>{/if}<button class="primary" disabled={!!busy||!selected.text} onclick={summarize}>{#if busy==='summary'}<LoaderCircle size={16} class="spin"/>Summarizing…{:else}<Sparkles size={16}/>{selected.summary?'Regenerate summary':'Create summary'}{/if}</button><p class="fine-print">Uses {config.ai_kind==='ollama'?'your local Ollama model':'your configured cloud provider'}. Review generated notes for accuracy.</p>
   {:else}<div class="ask-panel"><h2>A question about this conversation?</h2><p class="muted">Answers are drawn from your saved transcript.</p><div class="question-box"><input bind:value={question} onkeydown={(e)=>{if(e.key==='Enter')ask();}} placeholder="What did we agree to do next?" aria-label="Question"/><button class="primary square" disabled={!!busy} onclick={ask} aria-label="Ask question">{#if busy==='ask'}<LoaderCircle class="spin" size={16}/>{:else}<ArrowUp size={18}/>{/if}</button></div>{#if answer}<div class="generated-text">{answer}</div>{/if}</div>{/if}
   </div>
  {:else}
   <header class="page-header"><div><p class="eyebrow">{page==='meetings'?'LESS NOTE-TAKING. MORE LISTENING.':'YOUR VOICE, IN WRITING'}</p><h1>{page==='meetings'?'Meetings':'History'}<span class="count">{filtered.length}</span></h1><p>{page==='meetings'?'Stay in the conversation. Keep what matters.':'All your words, right where you left them.'}</p></div>{#if page==='meetings'}<button class="secondary" onclick={()=>action(async()=>{await call('import_audio');await refresh();})}><FileAudio size={15}/>Import audio</button>{/if}</header>
   {#if !modelReady}<button class="setup-card" onclick={()=>{page='settings';settingsTab='models';}}><span class="setup-icon"><Download size={20}/></span><span><strong>A small download. A lot less typing.</strong><small>Choose your speech model to get started. Everything stays on your device.</small></span><ChevronRight size={18}/></button>{/if}
   {#if page==='meetings'}<div class="calendar-strip"><span>COMING UP</span><button class="text-button" disabled={!!busy} onclick={()=>action(async()=>{events=await call<any[]>('calendar_events',{provider:calendarProvider});},'events')}>Refresh calendar<RotateCcw size={12}/></button></div>{#each events as event}<button class="calendar-event" onclick={()=>action(async()=>{const id=await call<string>('start_recording',{kind:'meeting'});await refresh();toast(`Recording: ${event.title}`);})}><span><strong>{event.title}</strong><small>{new Date(event.start).toLocaleString()}</small></span><Mic size={15}/></button>{/each}{/if}
   <div class="list-toolbar"><div class="search"><Search size={16}/><input bind:value={query} placeholder={page==='meetings'?'Search your meetings':'Search your words'} aria-label="Search recordings"/>{#if query}<button class="icon-button" aria-label="Clear search" onclick={()=>query=''}><X size={13}/></button>{/if}</div><span class="list-caption">{page==='meetings'?'YOUR NOTEBOOK':'RECENT DICTATIONS'}</span></div>
   {#if filtered.length}
    <div class="entry-list">{#each filtered as e}<button class="entry-row" onclick={()=>openEntry(e)}><span class="entry-icon">{#if e.kind==='meeting'}<NotebookPen size={18}/>{:else}<AudioLines size={18}/>{/if}</span><span class="entry-copy"><strong>{e.title||'Untitled recording'}</strong><span>{e.text||({recording:'Recording in progress…',processing:'Transcribing locally…',failed:'Needs attention · tap to retry',interrupted:'Interrupted · audio saved'}[e.status]||'Ready to transcribe')}</span></span><span class="entry-date">{date(e.created)}<small>{clock(e.duration)}</small></span><ChevronRight size={16}/></button>{/each}</div>
   {:else}<div class="empty-state"><div class="empty-art" aria-hidden="true"><span class="art-ring"></span><div class="paper"><span></span><span></span><span></span><span></span></div><div class="floating-mic">{#if page==='meetings'}<NotebookPen size={25} strokeWidth={1.5}/>{:else}<AudioLines size={27} strokeWidth={1.6}/>{/if}</div><span class="art-spark">✦</span></div><h2>{query?'No matching words yet.':page==='meetings'?'Be present. We’ll take notes.':'Your next thought starts here.'}</h2><p>{query?'Try a different word or clear your search.':page==='meetings'?'Record a conversation or import an audio file.\nYour notes and transcript will have a home here.':'An idea, a message, a sentence you don’t want to type.\nJust press your shortcut and say it.'}</p>{#if !query}<div class="shortcut-prompt"><kbd>{platform==='macos'?'⌘':'Ctrl'}</kbd><kbd>⇧</kbd><kbd>space</kbd><span>to {config.hold_to_talk?'hold and talk':'start talking'}</span></div>{/if}</div>{/if}
   {#if page==='meetings'&&entries.some(e=>e.kind==='meeting'&&e.text)}<div class="meeting-ask"><div><Sparkles size={16}/><strong>Connect the dots</strong></div><div class="question-box"><input bind:value={question} placeholder="Ask a question across your meetings…" aria-label="Question across meetings" onkeydown={(e)=>{if(e.key==='Enter')ask();}}/><button class="icon-button" disabled={!!busy} onclick={ask} aria-label="Ask">{#if busy==='ask'}<LoaderCircle class="spin" size={16}/>{:else}<ArrowUp size={17}/>{/if}</button></div>{#if answer}<div class="generated-text">{answer}</div>{/if}</div>{/if}
   <div class="page-foot"><span><ShieldCheck size={14}/>Private by default</span><span>{words?`${words.toLocaleString()} words you didn’t have to type`:'A little space for your thoughts.'}</span></div>
  {/if}
 </main>
 {#if page!=='settings'||phase!=='idle'}<div class="recording-dock" class:recording={phase==='recording'} class:processing={phase==='processing'}><div class="dock-icon">{#if phase==='processing'}<LoaderCircle size={20} class="spin"/>{:else}<Mic size={20}/>{/if}</div><div class="dock-copy"><strong>{phase==='recording'?'Listening…':phase==='processing'?'Finding your words…':page==='meetings'?'Make room for the conversation':'Ready when you are'}</strong><small>{phase==='recording'?`${clock(elapsed)} · Microphone`:phase==='processing'?`${Math.round(progress*100)}% · On your device`:page==='meetings'?'Record a meeting from your microphone':'Your voice. Your words. Your device.'}</small></div>{#if phase==='recording'}<div class="wave" aria-hidden="true">{#each [0.5,0.9,0.6,1,0.7,0.4,0.8] as n}<i style={`height:${8+Math.min(level*200,26)*n}px`}></i>{/each}</div>{/if}{#if phase==='processing'}<button class="secondary small" onclick={()=>call('cancel_job')}>Cancel</button>{:else}<button class="primary" class:stop-button={phase==='recording'} onclick={record} disabled={!native}>{#if phase==='recording'}<Square size={12} fill="currentColor"/>Finish{:else}<Mic size={15}/>{page==='meetings'?'Record meeting':'Start dictation'}{/if}</button>{/if}</div>{/if}
 {#if notice}<div class="toast" role="status"><Check size={15}/>{notice}</div>{/if}
 {#if deleteId}<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="delete-title" tabindex="-1"><Trash2 size={25}/><h2 id="delete-title">Delete this recording?</h2><p>Its transcript, notes, and retained audio will be removed from this device.</p><div><button class="secondary" onclick={()=>deleteId=''}>Keep it</button><button class="danger" onclick={remove}>Delete recording</button></div></div></div>{/if}
</div>

{/if}
